/**
 * Generate OG/social preview PNGs for capgo.app and product pages under apps/web/public/social/.
 * Covers: / (capgo_social.png), live-update, observe, native-build, notifications, enterprise, capgo-cli, the Capawesome
 * comparison, app_mobile, plugins, ionic-plugins, security-scanner, ci_cd, integrations, skills, agents.
 * Entries with `screenshot` frame a crop of a real console capture (public/landing-demos, regenerated by
 * Cap-go/capgo.app scripts/marketing-screenshots) instead of the drawn mock UI.
 * Usage: bun run generate:social-images
 */
import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, resolve } from 'node:path'
import { capgoLogoTileSvg, type LogoTileStyle } from './lib/capgo-logo-tile'
import { images, type SocialImage } from './lib/social-images'

const width = 2400
const height = 1260

function escapeText(value: string) {
  return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;')
}

function wrapText(value: string, maxChars: number) {
  const lines: string[] = []
  let current = ''

  for (const word of value.split(' ')) {
    const next = current ? `${current} ${word}` : word
    if (next.length > maxChars && current) {
      lines.push(current)
      current = word
    } else {
      current = next
    }
  }

  if (current) lines.push(current)
  return lines
}

function textLine(
  text: string,
  x: number,
  y: number,
  options: {
    size: number
    color: string
    weight?: number
    anchor?: 'start' | 'middle'
    opacity?: number
    hanging?: boolean
  },
) {
  const baseline = options.hanging ? ' dominant-baseline="hanging"' : ''
  return `<text x="${x}" y="${y}"${baseline} text-anchor="${options.anchor ?? 'start'}" font-family="Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif" font-size="${options.size}" font-weight="${options.weight ?? 500}" fill="${options.color}" opacity="${options.opacity ?? 1}">${escapeText(text)}</text>`
}

const logoTileStyle: LogoTileStyle = { radius: 42, innerRadius: 36, inset: 8, shadowX: 10, shadowY: 14, shadowOpacity: 0.16, accentOpacity: 0.12 }

function chips(items: string[], y: number, accent: string) {
  const gap = 24
  const widths = items.map((item) => 42 + item.length * 20)
  const total = widths.reduce((sum, value) => sum + value, 0) + gap * (items.length - 1)
  let x = (width - total) / 2

  return items
    .map((item, index) => {
      const chipWidth = widths[index]
      const output = `
        <rect x="${x}" y="${y}" width="${chipWidth}" height="64" rx="32" fill="#ffffff" stroke="${accent}" stroke-opacity="0.22"/>
        <circle cx="${x + 32}" cy="${y + 32}" r="8" fill="${accent}"/>
        ${textLine(item, x + 56, y + 20, { size: 24, color: '#334155', weight: 700, hanging: true })}`
      x += chipWidth + gap
      return output
    })
    .join('')
}

function renderCodePanel(image: SocialImage, bodyY = 900, scale = 1) {
  const x = 285
  const y = bodyY + (900 - 836) * scale

  const lines = image.codeLines
    .map((line, index) => {
      const color = index === 0 ? image.accent : index === 1 ? '#dbeafe' : '#94a3b8'
      return textLine(line, x + 52, y + 92 + index * 52, { size: 30, color, weight: index === 0 ? 800 : 600 })
    })
    .join('')

  return `
    <rect x="${x}" y="${y}" width="900" height="352" rx="34" fill="#0f172a"/>
    <rect x="${x + 24}" y="${y + 24}" width="852" height="304" rx="24" fill="#020617"/>
    <circle cx="${x + 58}" cy="${y + 54}" r="11" fill="#ef4444"/>
    <circle cx="${x + 94}" cy="${y + 54}" r="11" fill="#f59e0b"/>
    <circle cx="${x + 130}" cy="${y + 54}" r="11" fill="#22c55e"/>
    ${lines}`
}

function renderCards(image: SocialImage, bodyY = 900, scale = 1) {
  return image.cards
    .map((card, index) => {
      const x = 1235
      const y = bodyY + (914 - 836) * scale + index * 176 * scale
      return `
        <rect x="${x + 8}" y="${y + 12}" width="392" height="138" rx="30" fill="#0f172a" opacity="0.12"/>
        <rect x="${x}" y="${y}" width="392" height="138" rx="30" fill="#ffffff" stroke="#d8e3f1"/>
        ${textLine(card.label, x + 34, y + 50, { size: 25, color: '#64748b', weight: 700 })}
        ${textLine(card.value, x + 34, y + 104, { size: 48, color: '#0f172a', weight: 900 })}`
    })
    .join('')
}

function renderPhone(image: SocialImage, bodyY = 900, scale = 1) {
  const x = 1695
  const y = bodyY + (792 - 836) * scale
  const phoneHeight = 438 * scale
  const rowHeight = 52
  const rowGap = 18
  const rowStart = y + 188
  const rows = image.phoneRows
    .map((row, index) => {
      const rowY = rowStart + index * (rowHeight + rowGap)
      return `
        <rect x="${x + 54}" y="${rowY}" width="310" height="${rowHeight}" rx="18" fill="#111827"/>
        <circle cx="${x + 88}" cy="${rowY + rowHeight / 2}" r="9" fill="${image.accent}"/>
        ${textLine(row, x + 112, rowY + 35, { size: 23, color: '#e5e7eb', weight: 700 })}`
    })
    .join('')

  return `
    <rect x="${x + 18}" y="${y + 18}" width="430" height="${phoneHeight}" rx="66" fill="#0f172a" opacity="0.18"/>
    <rect x="${x}" y="${y}" width="430" height="${phoneHeight}" rx="66" fill="#020617"/>
    <rect x="${x + 26}" y="${y + 34}" width="378" height="${phoneHeight - 68}" rx="44" fill="#f8fbff"/>
    <rect x="${x + 152}" y="${y + 48}" width="126" height="18" rx="9" fill="#020617" opacity="0.82"/>
    <rect x="${x + 54}" y="${y + 94}" width="310" height="70" rx="24" fill="${image.accentSoft}"/>
    ${textLine(image.phoneTitle, x + 76, y + 138, { size: 26, color: '#0f172a', weight: 900 })}
    ${rows}`
}

/** Crop the console capture with ImageMagick and embed it as a PNG data URI (rsvg cannot read webp). */
function screenshotDataUri(image: SocialImage, targetWidth: number) {
  const shot = image.screenshot!
  const source = resolve('apps/web/public/landing-demos', shot.file)
  const out = resolve(tempDir, `${image.slug}-shot.png`)
  const { x, y, width: w, height: h } = shot.crop
  const magick = findTool('magick')
  if (!magick) throw new Error(`Unable to crop ${source}. Install ImageMagick.`)
  const result = spawnSync(magick, [source, '-crop', `${w}x${h}+${x}+${y}`, '+repage', '-resize', `${targetWidth}x`, out], { stdio: 'inherit' })
  if (result.status !== 0) throw new Error(`Unable to crop ${source}. Install ImageMagick.`)
  return `data:image/png;base64,${readFileSync(out).toString('base64')}`
}

function renderScreenshotSurface(image: SocialImage, browserY: number, browserHeight: number) {
  const x = 178
  const w = 2044
  const headerH = 72
  const toolbarY = browserY + headerH / 2
  const bodyY = browserY + headerH
  const bodyH = browserHeight - headerH

  return `
    <defs><clipPath id="shot-clip"><rect x="${x}" y="${bodyY}" width="${w}" height="${bodyH}" rx="0"/></clipPath></defs>
    <rect x="${x + 4}" y="${browserY + 26}" width="${w}" height="${browserHeight}" rx="42" fill="${image.accent}" opacity="0.18"/>
    <rect x="${x}" y="${browserY}" width="${w}" height="${browserHeight}" rx="42" fill="#0f172a" stroke="#1e293b"/>
    <circle cx="${x + 62}" cy="${toolbarY}" r="12" fill="#ef4444"/>
    <circle cx="${x + 100}" cy="${toolbarY}" r="12" fill="#f59e0b"/>
    <circle cx="${x + 138}" cy="${toolbarY}" r="12" fill="#22c55e"/>
    <rect x="${x + 206}" y="${toolbarY - 23}" width="420" height="46" rx="23" fill="#1e293b"/>
    ${textLine('console.capgo.app', x + 246, toolbarY - 11, { size: 22, color: '#94a3b8', weight: 700, hanging: true })}
    <image href="${screenshotDataUri(image, w)}" x="${x}" y="${bodyY}" width="${w}" height="${bodyH}" preserveAspectRatio="xMidYMin slice" clip-path="url(#shot-clip)"/>`
}

function renderBrowserSurface(image: SocialImage, browserY: number, browserHeight: number) {
  const x = 178
  const w = 2044
  const headerH = 72
  const chromeY = browserY + 24
  const toolbarY = browserY + headerH - 8
  const bodyY = browserY + headerH + 16
  const bodyH = browserHeight - headerH - 16
  const scale = bodyH / 532

  return `
    <rect x="${x + 4}" y="${browserY + 26}" width="${w}" height="${browserHeight}" rx="42" fill="#cdefff" opacity="0.48"/>
    <rect x="${x}" y="${browserY}" width="${w}" height="${browserHeight}" rx="42" fill="#ffffff" stroke="#dce9f8"/>
    <rect x="${x}" y="${browserY}" width="${w}" height="${headerH}" rx="42" fill="#f8fbff"/>
    <rect x="${x}" y="${bodyY}" width="${w}" height="${bodyH}" fill="#f8fbff"/>
    <circle cx="${x + 62}" cy="${toolbarY}" r="12" fill="#ef4444"/>
    <circle cx="${x + 100}" cy="${toolbarY}" r="12" fill="#f59e0b"/>
    <circle cx="${x + 138}" cy="${toolbarY}" r="12" fill="#22c55e"/>
    <rect x="${x + 206}" y="${toolbarY - 23}" width="390" height="46" rx="23" fill="#eef6ff"/>
    ${textLine('capgo.app / ' + image.slug, x + 246, toolbarY + 8, { size: 22, color: '#64748b', weight: 700, hanging: true })}
    <circle cx="${x + w - 148}" cy="${toolbarY}" r="14" fill="${image.accent}" opacity="0.22"/>
    <circle cx="${x + w - 106}" cy="${toolbarY}" r="14" fill="${image.accent}" opacity="0.42"/>
    ${renderCodePanel(image, bodyY, scale)}
    ${renderCards(image, bodyY, scale)}
    ${renderPhone(image, bodyY, scale)}`
}

function renderSvg(image: SocialImage) {
  const logoSize = 100
  const logoX = width / 2 - logoSize / 2
  const logoY = 52
  const eyebrowSize = 22
  const titleSize = image.title.some((line) => line.length > 31) ? 96 : 108
  const titleLineHeight = titleSize + 18
  const subtitleSize = 30
  const subtitleLineHeight = 40
  const subtitleLines = wrapText(image.subtitle, 72).slice(0, 2)
  const chipsHeight = 64

  const eyebrowY = logoY + logoSize + 40
  const titleY = eyebrowY + eyebrowSize + 48
  const subtitleY = titleY + image.title.length * titleLineHeight + 40
  // Screenshot cards let the real UI carry the detail: no subtitle, so the frame gets more height.
  const subtitleBottom = image.screenshot ? subtitleY - 40 : subtitleY + subtitleLines.length * subtitleLineHeight
  // Chips sit below the subtitle (it can wrap to two lines); the browser frame takes the remaining height.
  const chipsY = subtitleBottom + 32
  const browserY = image.screenshot ? subtitleBottom + 56 : chipsY + chipsHeight + 40
  const browserHeight = height - 40 - browserY

  const titleSvg = image.title
    .map((line, index) =>
      textLine(line, width / 2, titleY + index * titleLineHeight, {
        size: titleSize,
        color: '#101827',
        weight: 950,
        anchor: 'middle',
        hanging: true,
      }),
    )
    .join('')

  const subtitleSvg = subtitleLines
    .map((line, index) =>
      textLine(line, width / 2, subtitleY + index * subtitleLineHeight, {
        size: subtitleSize,
        color: '#475569',
        weight: 650,
        anchor: 'middle',
        hanging: true,
      }),
    )
    .join('')

  return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#fbfdff"/>
      <stop offset="0.58" stop-color="#f7fbff"/>
      <stop offset="1" stop-color="${image.accentSoft}"/>
    </linearGradient>
    <radialGradient id="glow" cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(${width / 2} ${browserY + browserHeight / 2}) rotate(90) scale(620 900)">
      <stop stop-color="${image.accent}" stop-opacity="0.24"/>
      <stop offset="0.55" stop-color="${image.accent}" stop-opacity="0.10"/>
      <stop offset="1" stop-color="${image.accent}" stop-opacity="0"/>
    </radialGradient>
    <pattern id="dots" width="28" height="28" patternUnits="userSpaceOnUse">
      <circle cx="2" cy="2" r="2" fill="#9eb7d1" opacity="0.42"/>
    </pattern>
  </defs>
  <rect width="${width}" height="${height}" fill="url(#bg)"/>
  <rect width="${width}" height="${height}" fill="url(#dots)"/>
  <rect width="${width}" height="${height}" fill="url(#glow)"/>
  ${capgoLogoTileSvg(logoX, logoY, logoSize, image.accent, logoTileStyle)}
  ${textLine(image.eyebrow.toUpperCase(), width / 2, eyebrowY, { size: eyebrowSize, color: image.accent, weight: 900, anchor: 'middle', hanging: true })}
  ${titleSvg}
  ${image.screenshot ? '' : subtitleSvg}
  ${image.screenshot ? '' : chips(image.chips, chipsY, image.accent)}
  ${image.screenshot ? renderScreenshotSurface(image, browserY, browserHeight) : renderBrowserSurface(image, browserY, browserHeight)}
</svg>`
}

// Image tools are resolved from fixed system directories instead of $PATH, so a writable
// PATH entry cannot substitute the binary these scripts execute.
const toolDirs = ['/opt/homebrew/bin', '/usr/local/bin', '/usr/bin', '/bin']

function findTool(command: string) {
  return toolDirs.map((dir) => resolve(dir, command)).find((candidate) => existsSync(candidate)) ?? null
}

function renderPng(svgPath: string, output: string) {
  mkdirSync(dirname(output), { recursive: true })

  const rsvg = findTool('rsvg-convert')
  if (rsvg) {
    const result = spawnSync(rsvg, ['-w', String(width), '-h', String(height), '-f', 'png', '-o', output, svgPath], { stdio: 'inherit' })
    if (result.status === 0) return
  }

  const magick = findTool('magick')
  if (magick) {
    const result = spawnSync(magick, [svgPath, '-resize', `${width}x${height}!`, output], { stdio: 'inherit' })
    if (result.status === 0) return
  }

  throw new Error('Unable to render social images. Install rsvg-convert or ImageMagick.')
}

const tempDir = mkdtempSync(resolve(tmpdir(), 'capgo-social-'))

try {
  for (const image of images) {
    const svg = renderSvg(image)
    const svgPath = resolve(tempDir, `${image.slug}.svg`)
    const output = resolve(image.output)
    writeFileSync(svgPath, svg)
    renderPng(svgPath, output)
    console.log(`Generated ${output}`)
  }
} finally {
  if (existsSync(tempDir)) rmSync(tempDir, { recursive: true, force: true })
}
